async ({ workspace: { read, glob }, git: { status, log } }) => {
  const [files, contrib, action, st, lg] = await Promise.all([
    glob(["**/*", "!node_modules/**", "!dist/**", "!.git/**"], { limit: 300 }),
    read("CONTRIBUTING.md", { format: "raw" }),
    read("action.yml", { format: "raw" }),
    status(["--short", "--branch"]),
    log(["--oneline", "-10"]),
  ]);
  return { files: files.entries, contrib, action, st: st.stdout, lg: lg.stdout };
}
